1	package main
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"io"
7		"strings"
8		"testing"
9	)
10	
11	// repeatReader 无限重复输出单个字节 n 次，用于在不分配整块 64 MiB 的情况下
12	// 构造超长输入，同时让读路径经过大量 64 KiB 缓冲填充。
13	type repeatReader struct {
14		b byte
15		n int
16	}
17	
18	func (r *repeatReader) Read(p []byte) (int, error) {
19		if r.n == 0 {
20			return 0, io.EOF
21		}
22		c := len(p)
23		if c > r.n {
24			c = r.n
25		}
26		for i := range p[:c] {
27			p[i] = r.b
28		}
29		r.n -= c
30		return c, nil
31	}
32	
33	// failAfterReader 先透传前 n 个字节，随后返回固定错误，模拟真实读取故障。
34	type failAfterReader struct {
35		data []byte
36		n    int
37		err  error
38	}
39	
40	func (r *failAfterReader) Read(p []byte) (int, error) {
41		if r.n >= len(r.data) {
42			return 0, r.err
43		}
44		c := copy(p, r.data[r.n:])
45		r.n += c
46		if r.n >= len(r.data) {
47			return c, r.err
48		}
49		return c, nil
50	}
51	
52	// overlongLine 返回一段“合法 JSON 前缀 + 空白填充”的超长行内容，
53	// 总长为 maxIngestLineBytes+delta，且不含换行。前缀里的采样点绝不能被写入。
54	func overlongLine(delta int) io.Reader {
55		prefix := `[{"name":"cpu","timestamp":2000,"value":9},`
56		return io.MultiReader(
57			strings.NewReader(prefix),
58			&repeatReader{b: ' ', n: maxIngestLineBytes + delta - len(prefix)},
59		)
60	}
61	
62	func decodeResultLine(t *testing.T, line string) map[string]interface{} {
63		t.Helper()
64		var m map[string]interface{}
65		if err := json.Unmarshal([]byte(line), &m); err != nil {
66			t.Fatalf("invalid JSON result %q: %v", line, err)
67		}
68		return m
69	}
70	
71	func TestRunIngestLineExactlyAtSizeLimitStillProcessed(t *testing.T) {
72		// 内容恰好 67,108,864 字节（外层一对方括号之间全部是空白），仍应进入处理。
73		input := io.MultiReader(
74			strings.NewReader("["),
75			&repeatReader{b: ' ', n: maxIngestLineBytes - 2},
76			strings.NewReader("]\n"),
77		)
78		var out bytes.Buffer
79		if code := runIngest(input, &out); code != 0 {
80			t.Fatalf("exit code = %d, want 0 for a line exactly at the limit", code)
81		}
82		lines := strings.Split(strings.TrimRight(out.String(), "\n"), "\n")
83		if len(lines) != 1 {
84			t.Fatalf("got %d output lines, want 1", len(lines))
85		}
86		m := decodeResultLine(t, lines[0])
87		if m["status"] != "ok" || m["added"].(float64) != 0 {
88			t.Fatalf("exact-limit line result = %v, want ok empty batch", m)
89		}
90	}
91	
92	func TestRunIngestOverlongLineIsIsolated(t *testing.T) {
93		input := io.MultiReader(
94			// 行 1：先成功写入 cpu 的一个点。
95			strings.NewReader(`[{"name":"cpu","timestamp":1000,"value":0.5,"labels":{"host":"a"}}]`+"\n"),
96			// 行 2：超长批次（超过上限 1 字节），带合法 JSON 前缀，整行失败。
97			overlongLine(1),
98			strings.NewReader("\n"),
99			// 行 3：后续查询必须照常得到结果，且只能看到行 1 的数据。
100			strings.NewReader(`{"op":"query","name":"cpu","start":0,"end":3000,"labels":{"host":"a"}}`+"\n"),
101		)
102		var out bytes.Buffer
103		code := runIngest(input, &out)
104		if code == 0 {
105			t.Fatalf("exit code = 0, want non-zero because a line exceeded the limit")
106		}
107	
108		lines := strings.Split(strings.TrimRight(out.String(), "\n"), "\n")
109		if len(lines) != 3 {
110			t.Fatalf("got %d output lines, want 3 (write ok, over-long error, query ok): %v",
111				len(lines), lines)
112		}
113	
114		first := decodeResultLine(t, lines[0])
115		if first["status"] != "ok" || first["added"].(float64) != 1 {
116			t.Fatalf("line 1 = %v, want successful write", first)
117		}
118	
119		bad := decodeResultLine(t, lines[1])
120		if bad["status"] != "error" || int(bad["line"].(float64)) != 2 {
121			t.Fatalf("line 2 = %v, want size-limit error on input line 2", bad)
122		}
123		if _, hasIndex := bad["index"]; hasIndex {
124			t.Fatalf("over-long line error must not carry index: %v", bad)
125		}
126		if _, hasConflict := bad["conflict"]; hasConflict {
127			t.Fatalf("over-long line error must not carry conflict: %v", bad)
128		}
129		msg, _ := bad["error"].(string)
130		if !strings.Contains(msg, "67108864") || !strings.Contains(msg, "single-line size limit") {
131			t.Fatalf("error message %q must state the size limit and its byte value", msg)
132		}
133	
134		q := decodeResultLine(t, lines[2])
135		if q["status"] != "ok" || q["op"] != "query" {
136			t.Fatalf("line 3 = %v, want successful query after the over-long line", q)
137		}
138		series := q["series"].([]interface{})
139		if len(series) != 1 {
140			t.Fatalf("query series = %v, want exactly the one committed point", series)
141		}
142		s0 := series[0].(map[string]interface{})
143		if s0["count"].(float64) != 1 || s0["average"].(float64) != 0.5 {
144			t.Fatalf("query after over-long line = %v, want only the earlier point", s0)
145		}
146	}
147	
148	func TestRunIngestConsecutiveOverlongLinesReportEachLineNumber(t *testing.T) {
149		input := io.MultiReader(
150			strings.NewReader("[]\n"),                // 行 1：正常
151			overlongLine(1), strings.NewReader("\n"), // 行 2：超长
152			overlongLine(5), strings.NewReader("\n"), // 行 3：再次超长（超 5 字节）
153			strings.NewReader("[]\n"), // 行 4：仍能正常处理
154		)
155		var out bytes.Buffer
156		code := runIngest(input, &out)
157		if code == 0 {
158			t.Fatalf("exit code = 0, want non-zero")
159		}
160		lines := strings.Split(strings.TrimRight(out.String(), "\n"), "\n")
161		if len(lines) != 4 {
162			t.Fatalf("got %d output lines, want 4: %v", len(lines), lines)
163		}
164		if decodeResultLine(t, lines[0])["status"] != "ok" {
165			t.Fatalf("line 1 = %v, want ok", lines[0])
166		}
167		for i, wantLine := range []int{2, 3} {
168			m := decodeResultLine(t, lines[1+i])
169			if m["status"] != "error" || int(m["line"].(float64)) != wantLine {
170				t.Fatalf("output %d = %v, want size error on input line %d", i+1, m, wantLine)
171			}
172			if _, hasIndex := m["index"]; hasIndex {
173				t.Fatalf("over-long error on line %d must not carry index: %v", wantLine, m)
174			}
175		}
176		if decodeResultLine(t, lines[3])["status"] != "ok" {
177			t.Fatalf("line 4 = %v, want ok after two over-long lines", lines[3])
178		}
179	}
180	
181	func TestRunIngestOverlongFinalLineWithoutNewlineReportedOnce(t *testing.T) {
182		input := io.MultiReader(
183			strings.NewReader("[]\n"), // 行 1：正常
184			overlongLine(1),           // 行 2：超长且输入在此直接结束，没有最后一个换行
185		)
186		var out bytes.Buffer
187		code := runIngest(input, &out)
188		if code == 0 {
189			t.Fatalf("exit code = 0, want non-zero")
190		}
191		lines := strings.Split(strings.TrimRight(out.String(), "\n"), "\n")
192		if len(lines) != 2 {
193			t.Fatalf("got %d output lines, want exactly 2 (ok + one error, no duplicate): %v",
194				len(lines), lines)
195		}
196		if decodeResultLine(t, lines[0])["status"] != "ok" {
197			t.Fatalf("line 1 = %v, want ok", lines[0])
198		}
199		m := decodeResultLine(t, lines[1])
200		if m["status"] != "error" || int(m["line"].(float64)) != 2 {
201			t.Fatalf("final output = %v, want one error on input line 2", m)
202		}
203	}
204	
205	func TestRunIngestOverlongWhitespaceLineStillFails(t *testing.T) {
206		// 上限以内的空白行不产生结果；超过上限的空白行仍是一条超长失败行。
207		input := io.MultiReader(
208			strings.NewReader(`{"op":"query","name":"m","start":0,"end":1}`+"\n"),     // 行 1
209			&repeatReader{b: ' ', n: maxIngestLineBytes + 1}, strings.NewReader("\n"), // 行 2
210			strings.NewReader("   \n"), // 行 3：上限以内空白，只占行号
211			strings.NewReader(`{"op":"query","name":"m","start":0,"end":1}`+"\n"), // 行 4
212		)
213		var out bytes.Buffer
